-- Mailchimp unsubscribes and bounces, applied automatically (MailchimpAudienceService).
--   mailchimp_audience_events – each one, from the webhook or the daily check
--   mailchimp_audience_syncs  – how far the daily check has got
CREATE TABLE "mailchimp_audience_events" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "mailchimp_audience_events_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"email" text NOT NULL,
	"kind" text NOT NULL,
	"at" timestamp with time zone NOT NULL,
	"reason" text,
	"via" text NOT NULL,
	"opted_out" integer DEFAULT 0 NOT NULL,
	"bounced" integer DEFAULT 0 NOT NULL,
	"opted_in_later" bigint[] DEFAULT '{}' NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"created_by" bigint,
	CONSTRAINT "mailchimp_audience_events_kind_check" CHECK ("mailchimp_audience_events"."kind" IN ('unsubscribe', 'cleaned')),
	CONSTRAINT "mailchimp_audience_events_via_check" CHECK ("mailchimp_audience_events"."via" IN ('webhook', 'check'))
);
--> statement-breakpoint
CREATE TABLE "mailchimp_audience_syncs" (
	"list_id" text PRIMARY KEY NOT NULL,
	"list_name" text,
	"changed_until" timestamp with time zone,
	"last_checked_at" timestamp with time zone,
	"last_error" text,
	"last_error_at" timestamp with time zone,
	"last_webhook_at" timestamp with time zone
);
--> statement-breakpoint
ALTER TABLE "mailchimp_audience_events" ADD CONSTRAINT "mailchimp_audience_events_created_by_staff_users_id_fk" FOREIGN KEY ("created_by") REFERENCES "public"."staff_users"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
CREATE UNIQUE INDEX "mailchimp_audience_events_uq" ON "mailchimp_audience_events" USING btree ("email","kind","at");--> statement-breakpoint
CREATE INDEX "mailchimp_audience_events_at_idx" ON "mailchimp_audience_events" USING btree ("at" DESC NULLS LAST);--> statement-breakpoint
CREATE TRIGGER t_mailchimp_audience_events_audit BEFORE INSERT ON mailchimp_audience_events
  FOR EACH ROW EXECUTE FUNCTION set_created_columns();
